; irq.asm -- chapter 12: the BIOS's interrupt routine on a painted stack
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "irq.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; C-BIOS's interrupt routine run with the stack at SYS_AREA, whose last 256
; bytes are painted first with $00 and then with $FF: the bytes the routine
; changed show how far down it wrote.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        VDP_REG 1, $A0          ; the display off, its interrupt on
        im 1
        ld hl, $F280
        ld b, 0                 ; 256 bytes
p00:    ld (hl), $00            ; the stack's memory painted $00
        inc hl
        djnz p00
        ei
        halt                    ; one interrupt, on this stack
        di
m1:     nop                     ; the debugger reads the painted bytes here ...
        ld hl, $F280
        ld b, 0                 ; 256 bytes
pFF:    ld (hl), $FF            ; the stack's memory painted $FF
        inc hl
        djnz pFF
        ei
        halt
        di
m2:     nop                     ; ... and here
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
